import { createRouter, createWebHashHistory } from 'vue-router'
import { MANAGERS, ROLE_HOME, ALLOWED_ROLES } from '@/config/managers.config'

const routes = [
    // ── Публичные ─────────────────────────────────────────
    {
        path:      '/login',
        name:      'login',
        component: () => import('./pages/LoginComponent.vue'),
        meta:      { guestOnly: true },
    },

    // ── Главная ───────────────────────────────────────────
    {
        path:      '/',
        name:      'main',
        component: () => import('./pages/MainDataComponent.vue'),
        meta:      { requiresAuth: true },
    },

    // ── Страницы менеджеров — берутся из конфига ──────────
    ...MANAGERS.map(m => ({
        path:      m.route,
        name:      m.id,
        component: m.component,
        meta:      { requiresAuth: true, roles: ['super', m.role] },
    })),

    // ── 404 ───────────────────────────────────────────────
    {
        path:      '/:pathMatch(.*)*',
        name:      'error',
        component: () => import('./pages/ErrorComponent.vue'),
        meta:      { requiresAuth: true },
    },
]

const router = createRouter({
    history: createWebHashHistory(),
    routes,
})

// ── Guard ─────────────────────────────────────────────────
router.beforeEach((to, from, next) => {
    let authData = null
    try {
        const raw = localStorage.getItem('sale-auth')
        authData  = raw ? JSON.parse(raw) : null
    } catch {
        localStorage.removeItem('sale-auth')
    }

    const role = authData?.role
        ? String(authData.role).trim().toLowerCase()
        : null

    if (to.meta.requiresAuth && !authData) {
        next('/login')
        return
    }

    if (authData && !ALLOWED_ROLES.includes(role)) {
        next('/login')
        return
    }

    if (to.meta.roles && !to.meta.roles.includes(role)) {
        next(ROLE_HOME[role] || '/')
        return
    }

    if (to.meta.guestOnly && authData) {
        next(ROLE_HOME[role] || '/')
        return
    }

    next()
})

export default router