<template>
  <div class="main-container">
    <div class="section-header">
      <img src="../src/assets/images/photo-png/logo.png" alt="Logo">

      <TimeComponent v-if="isDesktop"/>
      <WeatherComponent v-if="isDesktop"/>

      <div class="d-flex justify-space-around align-center">
        <v-icon
            v-if="isLoginChecked && userStatus.isLogin"
            :style="{ margin: '0 5px', color: userStatus.color }"
        >
          mdi-account-check
        </v-icon>

        <v-icon
            v-if="isLoginChecked && userStatus.isBlocked"
            style="margin: 0 5px; color: red"
        >
          mdi-account-remove
        </v-icon>

        <v-btn
            id="menu-activator"
            color="amber-darken-4"
            size="small"
            :disabled="userStatus.isBlocked"
        >
          <span v-if="!isDesktop" style="display:flex;align-items:center;gap:3px">
            <v-icon>mdi-menu</v-icon>
            Меню
          </span>
          <span v-else>Навигация</span>
        </v-btn>

        <v-menu activator="#menu-activator">
          <v-list style="margin-top: 5px">
            <v-list-item
                v-for="(item, index) in menuItems"
                :key="index"
                :value="index"
                @click="chooseOperation(item)"
                :style="{ color: item.color }"
            >
              <v-list-item-title>
                <v-icon :icon="item.icon" style="margin: 0 3px 0 0" :style="{ color: item.color }"/>
                {{ item.title }}
              </v-list-item-title>
            </v-list-item>
          </v-list>
        </v-menu>
      </div>
    </div>
    <div class="section-body">

      <!-- Лёгкий прелоадер пока идёт проверка авторизации -->
      <transition name="fade">
        <div class="light-preloader" v-if="!isLoginChecked">
          <div class="lp-bar">
            <div class="lp-bar-fill"></div>
          </div>
          <div class="lp-text">Проверка авторизации...</div>
        </div>
      </transition>

      <transition name="fade">
        <router-view v-if="isLoginChecked" @updateUserStatus="checkAuth"/>
      </transition>

    </div>
    <div class="section-asside">
      <div class="section-asside__title">UNION DASHBOARD</div>
      <div class="section-asside__logo">
        <img src="./assets/images/photo-png/logo.png" alt="">
      </div>
    </div>
    <div class="section-footer">
      © KIBERNETIKI
      <sup>
        2026<span v-if="footerYear !== '2026'"> - {{ footerYear }}</span>
      </sup>
    </div>
  </div>

  <!-- ── Диалог выхода ─────────────────────────────── -->
  <div class="text-center">
    <v-dialog v-model="dialog" max-width="400" persistent>
      <v-card prepend-icon="mdi-information" :text="dialogText" :title="dialogTitle">
        <template #actions>
          <v-spacer/>
          <v-btn @click="logOut" color="success">Выйти</v-btn>
          <v-btn @click="dialog = false" color="red">Отмена</v-btn>
        </template>
      </v-card>
    </v-dialog>
  </div>
  <!-- ── Snackbar ───────────────────────────────────── -->
  <div class="text-center">
    <v-snackbar v-model="snackbar" multi-line timeout="3000" style="margin-bottom: 60px">
      {{ snackbarText }}
      <template #actions>
        <v-btn color="red" variant="text" @click="snackbar = false">Закрыть</v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import TimeComponent from '@/components/header/TimeComponent.vue'
import WeatherComponent from '@/components/header/WeatherComponent.vue'
import {MANAGERS, ROLE_HOME, MANAGER_ROLES, getManagerColor} from '@/config/managers.config'

const DESKTOP_BREAKPOINT = 960

export default {
  name: 'App',
  components: {WeatherComponent, TimeComponent},
  data() {
    return {
      isLoginChecked: false,
      currentRole: null,
      footerYear: '',
      screenWidth: window.innerWidth,
      loginState: null,
      loginColor: 'gray',
      dialog: false,
      dialogText: '',
      dialogTitle: '',
      snackbar: false,
      snackbarText: '',
    }
  },
  computed: {
    isDesktop() {
      return this.screenWidth > DESKTOP_BREAKPOINT
    },
    userStatus() {
      return {
        isLogin: this.loginState === 'login',
        isBlocked: this.loginState === 'blocked',
        color: this.loginColor,
      }
    },
    menuItems() {
      const LOGOUT_ITEM = {title: 'Выйти', icon: 'mdi-logout-variant', color: 'red', action: 'logout'}

      // super видит все страницы менеджеров
      if (this.currentRole === 'super') {
        return [
          {title: 'Главная', icon: 'mdi-home', color: '', route: '/'},
          ...MANAGERS.map(m => ({
            title: m.name,
            icon: 'mdi-folder-open',
            color: '',
            route: m.route,
          })),
          LOGOUT_ITEM,
        ]
      }

      // Менеджер видит только свою страницу
      const manager = MANAGERS.find(m => m.role === this.currentRole)
      if (manager) {
        return [
          {title: manager.name, icon: 'mdi-folder-open', color: '', route: manager.route},
          LOGOUT_ITEM,
        ]
      }

      // promo и остальные — только главная
      return [
        {title: 'Главная', icon: 'mdi-home', color: '', route: '/'},
        LOGOUT_ITEM,
      ]
    },
  },
  async mounted() {
    this.footerData()
    window.addEventListener('resize', this.updateWidth)
    await this.checkAuth()
  },
  beforeUnmount() {
    window.removeEventListener('resize', this.updateWidth)
  },
  methods: {
    // ── Auth ────────────────────────────────────────────
    getLocalAuthData() {
      try {
        return JSON.parse(localStorage.getItem('sale-auth'))
      } catch {
        localStorage.removeItem('sale-auth')
        return null
      }
    },
    async checkAuth(authData = null) {
      const localAuth = authData || this.getLocalAuthData()

      localStorage.removeItem('checkLoadStatus')

      if (!localAuth) {
        this.resetAuth()
        setTimeout(() => this.$router.replace('/login'), 1000)
        return
      }

      const role = String(localAuth.role || '').trim().toLowerCase()

      if (!MANAGER_ROLES.includes(role) && role !== 'super' && role !== 'promo') {
        this.resetAuth()
        this.$router.replace('/login')
        return
      }

      this.currentRole = role

      try {
        const response = await fetch(
            'https://script.google.com/macros/s/AKfycbzZyyerGTUCYlCEdspNAwYkzfELY87SxYGc_ai6slWxF0zrLiFwXWZ2ewAEcoR41E3bmQ/exec'
        ).then(r => r.json())

        if (!response || !Array.isArray(response.stuff)) {
          throw new Error('Invalid auth response format')
        }

        const found = response.stuff.find(item => item.LoginName === localAuth.login)

        if (!found) {
          this.resetAuth()
          setTimeout(() => this.$router.replace('/login'), 1000)
          return
        }

        setTimeout(() => {
          this.isLoginChecked = true
          this.loginState = 'login'
          this.loginColor = getManagerColor(role) || (role === 'super' ? 'green' : role === 'promo' ? 'dodgerblue' : 'gray')
          this.$router.replace(ROLE_HOME[role] || '/login')
        }, 1000)

      } catch (error) {
        console.error(error)
        this.snackbarText = 'Ошибка загрузки данных с сервера, перезагрузите страницу'
        this.snackbar = true
        this.resetAuth()
        setTimeout(() => this.$router.replace('/login'), 1000)
      }
    },
    resetAuth() {
      localStorage.removeItem('sale-auth')
      localStorage.removeItem('checkLoadStatus')
      sessionStorage.removeItem('sale-auth')

      this.currentRole = null
      this.isLoginChecked = true
      this.loginState = 'blocked'
      this.loginColor = 'gray'
    },

    // ── Navigation ──────────────────────────────────────
    chooseOperation(item) {
      if (item.action === 'logout') {
        this.dialogTitle = 'Выход'
        this.dialogText = 'Вы уверены, что хотите выйти?'
        this.dialog = true
        return
      }

      if (localStorage.getItem('checkLoadStatus') !== 'loaded') {
        this.snackbarText = 'Дождитесь выполнения операции'
        this.snackbar = true
        return
      }

      if (item.route) {
        this.$router.push(item.route)
      }
    },
    logOut() {
      localStorage.removeItem('sale-auth')
      localStorage.removeItem('checkLoadStatus')
      sessionStorage.removeItem('sale-auth')
      window.location.href = window.location.origin + '/#/login'
      window.location.reload()
    },

    // ── Utils ───────────────────────────────────────────
    footerData() {
      this.footerYear = new Date().getFullYear().toString()
    },
    updateWidth() {
      this.screenWidth = window.innerWidth
    },
  },
}
</script>

